using System;using System.IO;using System.Collections.Generic;using ScoreModern.RecoveredFragments;
class InputPitchTokenProof {static int Main(string[] a){try{var state=new InputPitchState();var values=new List<float>();foreach(string token in a[0].TrimEnd(';').Split('/')){float? v=InputPitchToken.Parse(token,state);if(v.HasValue)values.Add(v.Value);}byte[] original=File.ReadAllBytes(a[1]);int count=BitConverter.ToInt16(original,0);if(values.Count!=count)throw new Exception("Token count");for(int n=0;n<count;n++)if(BitConverter.ToInt32(BitConverter.GetBytes(values[n]),0)!=BitConverter.ToInt32(original,2+n*4))throw new Exception("Token "+n+": "+values[n]+" != "+BitConverter.ToSingle(original,2+n*4));Console.WriteLine("PASS "+count+" original pitch token words.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}
